import {readAdminPreviewContext,clearAdminPreviewContext} from './admin-preview-context.js?v=20261029-fast-load';
import {installAccountSwitcher} from './linked-account-switch.mjs?v=20261109';
import {contractorRoute} from './contractor-routing.js?v=20260831-contractor-dashboard-split';
import {createClient} from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.0/+esm';
import {esc,visible,initialFields,SaveQueue,captureForm,validationIssue,isBirthDate} from './contractor-onboarding-model-date-20261112.mjs';
const env=window.__ENV||{},client=createClient(env.SUPABASE_URL,env.SUPABASE_ANON_KEY),root=document.querySelector('#onboarding');
void installAccountSwitcher(client).catch(() => {});
let state,editor=null,busy=false,previewId=null;
const portalTabs=[['dashboard','Dashboard'],['my-jobs','My Jobs'],['job-board','Job Board'],['schedule','Schedule'],['resources','Resources'],['messages','Messages'],['documents','Documents'],['payments','Payments'],['performance','Performance'],['video-library','Video Library']];
document.querySelector('#onPortalNav').innerHTML=`<a href="contractor-onboarding.html" aria-current="page">Onboarding</a>${portalTabs.map(([key,label])=>`<a href="${contractorRoute(key)}">${label}</a>`).join('')}<a href="contractor-academy/">Turnly Academy</a>`;
document.querySelector('.on-header .cp-native-wordmark').href=contractorRoute('dashboard');
document.addEventListener('click',event=>{const link=event.target.closest('.on-sidebar a,.on-header a');if(!link||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();void act(async()=>{if(editor){editor.capture?.();await editor.queue.flush();}location.assign(link.href);});});
async function api(action,data={}){const {data:{session}}=await client.auth.getSession();if(!session){location.replace('contractor-login.html');throw Error('Sign in to continue.');}if(previewId&&!['status','draft','signed_file'].includes(action))throw Error('Admin preview is read-only.');const r=await fetch(previewId?'/api/contractor-onboarding-preview':'/api/contractor-onboarding',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,...data,...(previewId?{profile_id:previewId}:{})}),signal:AbortSignal.timeout(55000)});const x=await r.json();if(!r.ok)throw Error(x.error||'Please try again.');return x;}
function error(e){let el=document.querySelector('#onError');if(!el){el=document.createElement('p');el.id='onError';el.className='on-error';el.role='alert';root.prepend(el);}el.textContent=e.message;el.scrollIntoView({block:'nearest'});}
async function act(fn){if(busy)return;busy=true;const alert=document.querySelector('#onError');if(alert)alert.textContent='';try{await fn();}catch(e){error(e);}finally{busy=false;}}
const backgroundLabels={needs_invitation:'Needs invitation',invited:'Invitation sent — check your email',in_progress:'Screening in progress',awaiting_review:'Screening completed — awaiting Turnly review',approved:'Approved by Turnly',on_hold:'Contact Turnly',existing_complete:'Complete'};
const labels={todo:'Not started',in_progress:'In progress',done:'Complete',in_review:'Awaiting review',rejected:'Needs changes',expired:'Expired',resign:'Signature required'};
async function load(){state=await api('status');editor=null;if(previewId){document.querySelector('#onPreviewBanner').innerHTML=`<strong>Admin preview: ${esc(state.identity.name)}</strong><p>Live checklist and saved draft. Form changes stay in this preview only. No signatures, uploads, or progress changes are submitted.</p><button id="exitPreview" type="button">Exit preview</button>`;document.querySelector('#exitPreview').onclick=()=>{clearAdminPreviewContext();location.assign('directory.html');};}if(state.personal_email?.required){personalEmail();return;}root.innerHTML=`<a href="contractor.html">← Workspace</a><p class="on-eyebrow">CONTRACTOR ONBOARDING</p><h1>Get ready to claim jobs</h1><p>Complete your forms and sign right here. Your drafts save automatically. Complete your required Academy training too. Once all required documents are approved and training is complete, job access activates automatically.</p>${state.account_approved?'<div class="on-card"><strong>You are ready for work.</strong><p>Your onboarding is complete.</p><a href="contractor.html">View available jobs →</a></div>':''}<progress class="on-progress" max="${state.requiredCount||1}" value="${state.doneCount||0}"></progress><div class="on-row"><strong>${state.doneCount} of ${state.requiredCount} required complete</strong><button class="secondary" id="refresh">Refresh status</button></div><div class="on-list">${state.items.map(i=>`<article class="on-card"><div class="on-row"><div><strong>${esc(i.title)}</strong><p>${i.waived?'Waived for you':i.required?'Required':'Optional'}${i.questionCount?' · '+i.questionCount+' questions':''}</p><span class="on-status ${esc(i.state)}">${esc(i.background?backgroundLabels[i.background.status]||labels[i.state]:labels[i.state]||i.state)}</span>${i.kind==='academy'?`<p>${esc(i.description)}</p>`:''}${i.submission?.reviewerNote?`<p>${esc(i.submission.reviewerNote)}</p>`:''}</div><button data-item="${esc(i.id)}">${i.kind==='academy'?'Open training site':i.state==='done'?'View':'Continue'} →</button></div></article>`).join('')}</div>`;root.querySelector('#refresh').onclick=()=>act(load);root.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>act(()=>openItem(b.dataset.item)));}
async function showDocument(action,data){const {url}=await api(action,data);if(previewId){document.querySelector('#document').innerHTML=`<a href="${esc(url)}" target="_blank" rel="noopener">Open submitted document</a>`;return;}const box=document.querySelector('#document');box.innerHTML=`<div id="pdfPreview"><p role="status">Loading document…</p></div><p><a href="${esc(url)}" target="_blank" rel="noopener">Open full-size document</a></p>`;try{const [file,renderer]=await Promise.all([api('file_content',{...data,kind:action}),import('./contractor-document-preview.mjs')]);await renderer.preview(document.querySelector('#pdfPreview'),file);}catch(e){document.querySelector('#pdfPreview').textContent=e.message;}}

async function openItem(id){const item=state.items.find(i=>i.id===id);if(item.kind==='academy'){if(previewId){alert(item.description);return;}location.href=item.trainingUrl;return;}root.innerHTML=`<button class="secondary" id="back">← Onboarding</button><h1>${esc(item.title)}</h1><p class="on-description">${esc(item.description)}</p><div id="onError" role="alert"></div>${item.submission?.signerName?`<div class="on-card">Signed by ${esc(item.submission.signerName)} · ${esc(labels[item.state]||item.state)}</div>`:''}<div class="on-actions">${item.hasDocument?'<button class="secondary" id="reference">Read document</button>':''}${item.submission?.hasFile?'<button class="secondary" id="signed">View submitted copy</button>':''}</div><div id="document"></div><div id="editor"></div>`;document.querySelector('#back').onclick=()=>act(async()=>{if(editor){editor.capture?.();await editor.queue.flush();}await load();});if(item.hasDocument)document.querySelector('#reference').onclick=()=>act(()=>showDocument('document',{item_id:id}));if(item.submission?.hasFile)document.querySelector('#signed').onclick=()=>act(()=>showDocument('signed_file',{submission_id:item.submission.id}));
 if(['done','in_review'].includes(item.state)&&['sign','form'].includes(item.kind)){document.querySelector('#editor').innerHTML='<p>This document has already been submitted. Use View submitted copy above to review it.</p>';return;}
 if(previewId&&!['sign','form'].includes(item.kind)){document.querySelector('#editor').innerHTML='<p>Read-only preview. Uploads and completion actions are available only in the contractor’s own session.</p>';return;}if(item.background)backgroundEditor(item);else if(['sign','form'].includes(item.kind))await formEditor(item);else if(['upload','background'].includes(item.kind))uploadEditor(item);else if(item.kind==='video')videoEditor(item);
 if(item.kind==='sign'&&item.hasDocument)await showDocument('document',{item_id:id});
 window.scrollTo(0,0);
}
function fieldHtml(q,values,confirm={}){const birth=isBirthDate(q),rawValue=values[q.id],value=birth&&/^\d{4}-\d{2}-\d{2}$/.test(String(rawValue||''))?String(rawValue).replace(/^(\d{4})-(\d{2})-(\d{2})$/,'$2/$3/$1'):rawValue,id='q-'+q.id,secret=q.sensitive||['tin','account','routing'].includes(q.type),attrs=`id="${esc(id)}" data-field="${esc(q.id)}" ${birth?'placeholder="MM/DD/YYYY" aria-describedby="'+esc(id)+'-format"':''} ${q.required?'required':''}`;
 let input;if(q.type==='check')input=`<label class="on-check"><input ${attrs} type="checkbox" ${value===true||value==='Agreed'?'checked':''}>${esc(q.label)}</label>`;
 else if(q.type==='multi')input=`<fieldset><legend>${esc(q.label)}${q.required?' *':''}</legend>${q.options.map(o=>`<label class="on-check"><input type="checkbox" data-multi="${esc(q.id)}" value="${esc(o)}" ${Array.isArray(value)&&value.includes(o)?'checked':''}>${esc(o)}</label>`).join('')}</fieldset>`;
 else{let control;if(['choice','yesno'].includes(q.type))control=`<select ${attrs}><option value="">Select…</option>${q.options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(q.type==='long')control=`<textarea ${attrs} maxlength="2000">${esc(value)}</textarea>`;else control=`<input ${attrs} type="${secret?'password':({date:'date',email:'email',phone:'tel',number:'number'}[q.type]||'text')}" autocomplete="off" maxlength="300" value="${esc(value)}">`;input=`<label for="${esc(id)}">${esc(q.label)}${birth?' (MM/DD/YYYY)':''}${q.required?' *':''}</label>${secret?`<div class="on-secret">${control}<button type="button" data-eye="${esc(id)}" aria-label="Show ${esc(q.label)}" aria-pressed="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div>`:control}`;if(q.confirm)input+=`<label>Confirm ${esc(q.label)}<input type="${secret?'password':'text'}" data-confirm="${esc(q.id)}" ${q.required?'required':''} value="${esc(confirm[q.id]||'')}" autocomplete="off"></label>`;}
 return `<div class="on-field" data-wrap="${esc(q.id)}">${input}${birth?`<p id="${esc(id)}-format" class="on-help">Enter month/day/four-digit year, for example 04/15/1994. A year alone is not accepted.</p>`:''}${q.help?`<p class="on-help">${esc(q.help)}</p>`:''}</div>`;}
async function formEditor(item){const loaded=await api('draft',{item_id:item.id}),old=loaded.draft;
 const e=editor={item,revision:loaded.revision,fields:old?.fields||initialFields(item,state.profile||{},state.identity||{}),signerName:old?.signerName||state.identity?.name||'',section:old?.section||0,confirm:{}};
 e.sections=[...new Set((item.fields||[]).map(q=>q.section||'Your information'))];e.sections.push('Review & sign');e.section=Math.min(e.section,e.sections.length-1);
 e.queue=new SaveQueue(async()=>{if(previewId)return;const snapshot={fields:structuredClone(e.fields),signerName:e.signerName,section:e.section};const r=await api('save',{item_id:item.id,version:item.version,revision:e.revision,draft:snapshot});e.revision=r.revision;},(text,isError)=>{const s=document.querySelector('#saveState');if(s){s.textContent=previewId?'Preview only — changes are not saved':text;s.className=isError?'on-error':'on-save';}});renderSection(e);}
function renderSection(e){const host=document.querySelector('#editor');host.innerHTML=`<div class="on-sections">${e.sections.map((s,n)=>`<button type="button" data-section="${n}" aria-current="${n===e.section?'step':'false'}">${n+1}. ${esc(s)}</button>`).join('')}</div><p id="saveState" class="on-save" role="status">${previewId?'Saved contractor draft — preview only':e.revision?'Saved draft restored':'Your progress saves as you type'}</p><form class="on-form on-card" id="form"><h2>${esc(e.sections[e.section])}</h2>${e.section===e.sections.length-1?`<p>Review the document and your answers before signing. Your signature will be saved with this version of the document.</p><div class="on-consent">${esc(state.consent)}</div><label>Full legal name<input id="signer" required autocomplete="name" value="${esc(e.signerName)}"></label><label class="on-check"><input id="consent" type="checkbox" required>I have reviewed this document and my answers, and agree to sign electronically.</label>`:(e.item.fields||[]).filter(q=>(q.section||'Your information')===e.sections[e.section]).map(q=>fieldHtml(q,e.fields,e.confirm)).join('')}<div class="on-actions">${e.section?'<button type="button" class="secondary" id="previous">Back</button>':''}<button type="submit">${e.section===e.sections.length-1?'Sign & submit':'Save & continue →'}</button><button type="button" class="secondary" id="saveExit">Save & finish later</button></div></form>`;
 const form=host.querySelector('form');if(previewId){host.querySelector('#saveExit').textContent='Return to checklist';if(e.section===e.sections.length-1){form.querySelector('[type=submit]').textContent='Check form validation';form.querySelector('#consent').required=false;form.querySelector('#consent').disabled=true;}}function conditions(){for(const q of e.item.fields||[]){const wrap=[...host.querySelectorAll('[data-wrap]')].find(x=>x.dataset.wrap===q.id);if(!wrap)continue;wrap.hidden=!visible(q,e.fields);wrap.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=wrap.hidden);}}conditions();
 form.addEventListener('input',ev=>{const t=ev.target;if(t.dataset.field){e.fields[t.dataset.field]=t.type==='checkbox'?t.checked:t.value;e.queue.changed();conditions();}else if(t.dataset.multi){e.fields[t.dataset.multi]=[...form.querySelectorAll('[data-multi]')].filter(x=>x.dataset.multi===t.dataset.multi&&x.checked).map(x=>x.value);e.queue.changed();conditions();}else if(t.id==='signer'){e.signerName=t.value;e.queue.changed();}else if(t.dataset.confirm){e.confirm[t.dataset.confirm]=t.value;t.setCustomValidity('');}});
 host.querySelectorAll('[data-eye]').forEach(b=>b.onclick=()=>{const i=document.getElementById(b.dataset.eye),show=i.type==='password';i.type=show?'text':'password';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',(show?'Hide':'Show')+' value');});
 const capture=e.capture=()=>{captureForm(form,e);e.queue.changed();};form.addEventListener('change',()=>{capture();conditions();});const go=async n=>{capture();const previous=e.section;e.section=n;try{await e.queue.flush();}catch(err){e.section=previous;throw err;}renderSection(e);window.scrollTo(0,0);};host.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>act(()=>go(Number(b.dataset.section))));if(e.section)host.querySelector('#previous').onclick=()=>act(()=>go(e.section-1));host.querySelector('#saveExit').onclick=()=>act(async()=>{capture();await e.queue.flush();await load();});
 form.onsubmit=ev=>{ev.preventDefault();act(async()=>{capture();const issue=validationIssue(e.item,e.fields,e.confirm,e.section===e.sections.length-1?null:e.sections[e.section]);if(issue){const target=e.sections.indexOf(issue.field.section||'Your information');if(target>=0&&target!==e.section)await go(target);throw Error(issue.message);}
 if(e.section<e.sections.length-1){await go(e.section+1);return;}if(previewId){document.querySelector('#saveState').textContent='Form validation passed in this preview. No signature was submitted; backend signing is not tested.';return;}e.queue.changed();await e.queue.flush();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await api('sign',{item_id:e.item.id,version:e.item.version,revision:e.revision,consent:document.querySelector('#consent').checked});await load();}finally{submit.disabled=false;}});};
}
function uploadEditor(item){document.querySelector('#editor').innerHTML=`<form class="on-form on-card" id="upload"><h2>${item.kind==='background'?'Background check documentation':'Upload your document'}</h2><p>PDF, JPG or PNG · up to 3 MB. Submitted files stay available in your documents.</p><label>Choose file<input id="file" type="file" accept="application/pdf,image/jpeg,image/png" required></label>${item.requiresExpiration?'<label>Expiration date<input id="expiration" type="date" required></label>':''}<button type="submit">Submit for review</button><p id="uploadState" role="status"></p></form>`;document.querySelector('#upload').onsubmit=ev=>{ev.preventDefault();act(async()=>{const f=document.querySelector('#file').files[0];if(f.size>3*1024*1024)throw Error('Choose a file no larger than 3 MB.');document.querySelector('#uploadState').textContent='Uploading…';const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f);});await api('upload',{item_id:item.id,mime:f.type,name:f.name,file:data,expiration:document.querySelector('#expiration')?.value});await load();});};}
function videoEditor(item){const u=new URL(item.videoUrl);if(u.protocol!=='https:')throw Error('Training video is unavailable. Contact Turnly.');document.querySelector('#editor').innerHTML=`<div class="on-card"><video class="on-video" controls playsinline src="${esc(u.href)}"></video><p>Watch the full training video to complete this step.</p><button id="watched" disabled>Complete training</button></div>`;const video=document.querySelector('video'),button=document.querySelector('#watched');let furthest=0;video.ontimeupdate=()=>{if(!video.seeking&&video.currentTime<=furthest+2)furthest=Math.max(furthest,video.currentTime);};video.onseeking=()=>{if(video.currentTime>furthest+2)video.currentTime=furthest;};video.onended=()=>{button.disabled=!(furthest>=video.duration-2);};button.onclick=()=>act(async()=>{await api('watched',{item_id:item.id});await load();});}
window.addEventListener('beforeunload',e=>{if(editor&&(editor.queue.dirty||editor.queue.pending)){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&editor?.queue.dirty)editor.queue.flush().catch(()=>{});});window.addEventListener('online',()=>{if(editor?.queue.dirty)editor.queue.flush().catch(()=>{});});document.querySelector('#signout').onclick=()=>act(async()=>{if(editor)await editor.queue.flush();await client.auth.signOut();location.replace('contractor-login.html');});
await act(async()=>{const context=readAdminPreviewContext();if(context?.enabled&&context.portal==='contractor'){const {data:{session}}=await client.auth.getSession();if(session){const {data:p}=await client.from('profiles').select('role,status').eq('id',session.user.id).maybeSingle();if(p?.role==='admin'&&p.status==='active')previewId=context.user;}}await load();});

window.addEventListener('pageshow',e=>{if(e.persisted&&!editor)act(load);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!editor&&document.querySelector('#refresh'))act(load);});

function backgroundEditor(item){const b=item.background;document.querySelector('#editor').innerHTML=`<section class="on-card"><h2>${esc(backgroundLabels[b.status]||'Background check')}</h2><ol><li>Turnly sends your Verified First invitation by email.</li><li>Open that invitation to provide consent, enter your information securely, and pay Verified First.</li><li>Turnly reviews the completed report and approves this requirement.</li></ol><p>${esc(b.contractor_note||'If you have not received an invitation, contact admin@turnlypros.com. Payment or completing the provider form does not automatically approve your account.')}</p>${b.sync_state==='pending'?'<p>Turnly is updating your checklist. Job access stays paused until the update is confirmed.</p>':''}<p>Other required documents and training must also be complete before accepting jobs.</p><a href="mailto:admin@turnlypros.com">Contact Turnly</a></section>`;}

function personalEmail(){
 root.innerHTML=`<h1>Your personal email</h1><p>Use an email you check regularly for your Turnly login and communications. Your documents and progress stay with this account.</p><form class="on-form on-card" id="personalEmail"><label>Personal email<input id="email" type="email" autocomplete="email" required value="${esc(state.identity.email)}"></label><button>Save email and continue</button><p id="emailStatus" role="status"></p></form><button class="secondary" id="emailConfirmed">I confirmed my email — continue</button><p>If you change your address, follow the confirmation instructions sent to your new address and, if requested, your previous address. Then return here. Contact admin@turnlypros.com if you cannot access the old inbox.</p>`;
 document.querySelector('#personalEmail').onsubmit=e=>{e.preventDefault();act(async()=>{
  const email=document.querySelector('#email').value.trim().toLowerCase();
  if(/(^|\.)indeed(email)?\.com$/i.test(email.split('@')[1]||''))throw Error('Enter your personal email, not your Indeed relay address.');
  const {data,error:err}=await client.auth.getUser();if(err)throw err;
  if(data.user.email.toLowerCase()!==email){const {error:err}=await client.auth.updateUser({email},{emailRedirectTo:location.origin+'/contractor-onboarding.html'});if(err)throw err;document.querySelector('#emailStatus').textContent='Check your email for confirmation instructions, then return here and click “I confirmed my email”.';return;}
  await api('confirm_personal_email');await load();
 });};
 document.querySelector('#emailConfirmed').onclick=()=>act(async()=>{await client.auth.refreshSession();await api('confirm_personal_email');await load();});
}
